"""Write the layout kit's generated files (ADR-008 D2, D7 R3).

From layout/include/overlay_contract.json (the overlay contract's table),
layout/include/kit/AGENTS.md.tmpl and the kit's samples
(layout/include/kit/<kind>/index.*), write:

- layout/include/kit/CONTRACT.md         the view's keys as tables
- layout/include/kit/<kind>/AI_PROMPT.md one file to paste into a chat AI:
                                          the instructions, the keys the kind
                                          reads and the kind's sample

and from layout/include/thumbnail_contract.json (template contract 2's
payload table), layout/include/kit/thumbnail/AGENTS.md.tmpl, the thumbnail
kit's sample (thumbnail.*, template.json) and the overlay sample state
layout/include/sample/singles.json:

- layout/include/kit/thumbnail/sample_payload.json  a payload as the app
                                                     hands it to onRender
- layout/include/kit/thumbnail/CONTRACT.md          the payload's keys
- layout/include/kit/thumbnail/AI_PROMPT.md         the thumbnail's one file

and from layout/include/result_contract.json (the result's payload table on
template contract 2, ADR-008 D7 R4), layout/include/kit/result/AGENTS.md.tmpl,
the result kit's sample (result.*) and the sample state's characters:

- layout/include/kit/result/sample_payload.json        a players' payload
- layout/include/kit/result/sample_payload_teams.json  a teams' payload
- layout/include/kit/result/CONTRACT.md                the payload's keys
- layout/include/kit/result/AI_PROMPT.md               the result's one file

All are committed and copied into a new design by core/LayoutKit. Run this
after changing any of the sources:

    python scripts/gen_layout_kit.py

tests/test_layout_kit.py fails when the committed files are not what this
writes (``Build()`` is compared, line endings aside).
"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
LAYOUT = ROOT / "layout"
KIT = LAYOUT / "include" / "kit"
CONTRACT = LAYOUT / "include" / "overlay_contract.json"
AGENTS_TEMPLATE = "AGENTS.md.tmpl"
SAMPLE_FILES = ("index.html", "index.css", "index.js")
FENCES = {"index.html": "html", "index.css": "css", "index.js": "js",
          "thumbnail.html": "html", "thumbnail.css": "css",
          "thumbnail.js": "js", "template.json": "json",
          "result.html": "html", "result.css": "css", "result.js": "js"}

# The overlay kinds a new design may be (core/LayoutKit.OVERLAY_KINDS), with
# their page's name and the view's groups they read first.
KINDS = {
    "scoreboard": ("BOARD のスコアボード", ("board", "tournament", "options")),
    "commentary": ("実況者の表示", ("commentary", "tournament", "options")),
    "top8": ("TOP 8 のブラケット", ("top8", "tournament", "options")),
}
GROUP_ORDER = ("board", "tournament", "commentary", "top8", "options")
GROUP_TITLES = {
    "board": "view.board（スコアボード）",
    "tournament": "view.tournament（大会）",
    "commentary": "view.commentary（実況者）",
    "top8": "view.top8（TOP 8）",
    "options": "view.options（表示の切り替え）",
}
HEADER = ("<!-- Generated by scripts/gen_layout_kit.py from "
          "layout/include/overlay_contract.json{sources}. Do not edit: "
          "change the sources and run the script. -->\n")

# The thumbnail's kit (core/LayoutKit.TEMPLATE_KINDS): its sample files, as
# they are in the kit and in a new design, and where its payload's sample
# data comes from (the sample state's roots a thumbnail reads, and board 1
# alone of score: the app's RENDER_BOARD).
THUMBNAIL = "thumbnail"
THUMBNAIL_CONTRACT = "thumbnail_contract.json"
THUMBNAIL_FILES = ("thumbnail.html", "thumbnail.css", "thumbnail.js",
                   "template.json")
THUMBNAIL_TEMPLATE = "template.json"
SAMPLE_PAYLOAD = "sample_payload.json"
SAMPLE_STATE = "singles"
SAMPLE_DATA_ROOTS = ("game", "tournamentInfo", "display_options")
SAMPLE_BOARD = "1"
# The template_id the sample payload names: a new design's is its folder.
SAMPLE_TEMPLATE_ID = "thumbnail_sample"
PAYLOAD_GROUPS = ("data", "config", "template")
PAYLOAD_TITLES = {
    "data": "payload.data（試合のデータ。Autona の state）",
    "config": "payload.config（サムネイルのページの設定）",
    "template": "payload.template（template.json の中身）",
}
THUMBNAIL_HEADER = (
    "<!-- Generated by scripts/gen_layout_kit.py from "
    "layout/include/thumbnail_contract.json{sources}. Do not edit: "
    "change the sources and run the script. -->\n")


def _cell(value):
    return str(value).replace("|", "\\|").replace("\n", " ")


def _empty(value):
    return "`" + json.dumps(value, ensure_ascii=False) + "`"


def _group(key):
    return key.split(".", 1)[0].split("[", 1)[0]


def _table(keys):
    lines = ["| キー | 型 | 値が無いとき | 説明 |", "|---|---|---|---|"]
    for row in keys:
        lines.append(f"| `{_cell(row['key'])}` | {row['type']} | "
                     f"{_empty(row['empty'])} | {_cell(row['ja'])} |")
    return "\n".join(lines)


def _sections(contract, groups, level):
    out = []
    for group in groups:
        keys = [row for row in contract["keys"] if _group(row["key"]) == group]
        if keys:
            out.append(f"{'#' * level} {GROUP_TITLES[group]}\n\n{_table(keys)}\n")
    return "\n".join(out)


def _placeholders(contract):
    return "\n".join(
        f"- `{name}`: " + " / ".join(f"`{value}`" for value in values)
        for name, values in contract["placeholders"].items())


def _contract_md(contract):
    return (
        HEADER.format(sources="")
        + f"\n# オーバーレイ契約 {contract['contract']} のキー\n\n"
        + contract["description"]["ja"] + "\n\n"
        + "キーの中の記号:\n\n" + _placeholders(contract) + "\n\n"
        + _sections(contract, GROUP_ORDER, 2))


def _demote(text):
    """Every Markdown heading outside code fences one level down, and the
    document's own title dropped."""
    out = []
    fenced = False
    titled = False
    for line in text.splitlines():
        if line.startswith("```"):
            fenced = not fenced
        elif not fenced and line.startswith("# ") and not titled:
            titled = True
            continue
        elif not fenced and line.startswith("#"):
            line = "#" + line
        out.append(line)
    return "\n".join(out).strip() + "\n"


def _ai_prompt(kind, contract, agents, samples):
    label, groups = KINDS[kind]
    others = [group for group in GROUP_ORDER if group not in groups]
    parts = [
        HEADER.format(sources=", layout/include/kit/AGENTS.md.tmpl and "
                      f"layout/include/kit/{kind}/"),
        f"\n# Autona のオーバーレイを作る: {label}（kind `{kind}`）\n",
        "この文書だけで作れるように、指示書・データのキーの表・動くサンプルをまとめています。"
        "あなた（AI）は利用者の頼みに合わせてサンプルを書き換え、"
        "**`index.html` / `index.css` / `index.js` の全文**をファイルごとに 1 つのコードブロックで返してください。"
        "利用者はそれを Autona の「新しいデザインを作る」で作ったフォルダ（`layout/<フォルダ名>/`）に上書き保存します。"
        "`settings.json` と `../include/` の中身は利用者の手元にあるので、返さなくてよいです。\n",
        "## 指示書\n",
        _demote(agents),
        f"## view のキー（{kind} で使うまとまり）\n",
        "ほかのまとまり（" + "・".join(f"`view.{group}`" for group in others)
        + "）も同じ `view` にあります（キーの全量はフォルダの `CONTRACT.md`）。"
        + "キーの中の記号:\n\n" + _placeholders(contract) + "\n",
        _sections(contract, groups, 3),
        "## サンプル（今フォルダにある 3 ファイル）\n",
    ]
    for name in SAMPLE_FILES:
        parts.append(f"### {name}\n\n```{FENCES[name]}\n"
                     f"{samples[name].rstrip()}\n```\n")
    return "\n".join(parts)


def _payload_table(keys):
    lines = ["| キー | 型 | 説明 |", "|---|---|---|"]
    for row in keys:
        lines.append(f"| `{_cell(row['key'])}` | {_cell(row['type'])} | "
                     f"{_cell(row['ja'])} |")
    return "\n".join(lines)


def _payload_sections(contract, level):
    out = []
    for group in PAYLOAD_GROUPS:
        keys = [row for row in contract["keys"]
                if row["key"].split(".", 1)[0] == group]
        out.append(f"{'#' * level} {PAYLOAD_TITLES[group]}\n\n"
                   f"{_payload_table(keys)}\n")
    return "\n".join(out)


def _picked(value, patterns):
    """`value` with only what a table key reaches: `patterns` are the keys'
    segments ("{X}" any key of a dict); a key that ends at a dict keeps it
    whole (an object row: country, character.{K})."""
    if not isinstance(value, dict):
        return value
    out = {}
    for key, child in value.items():
        rest = [pattern[1:] for pattern in patterns if pattern and (
            pattern[0] == key
            or (pattern[0].startswith("{") and pattern[0].endswith("}")))]
        if not rest:
            continue
        out[key] = child if any(not pattern for pattern in rest) \
            else _picked(child, rest)
    return out


def _sample_payload(contract, state, template):
    """The payload the thumbnail's sample is drawn with: the sample state's
    keys the table names (board SAMPLE_BOARD of score), the contract's
    sample config and the kit's template.json with its id."""
    data = {root: state[root] for root in SAMPLE_DATA_ROOTS if root in state}
    data["score"] = {SAMPLE_BOARD: state["score"][SAMPLE_BOARD]}
    data = _picked(data, [row["key"].split(".")[1:] for row in contract["keys"]
                          if row["key"].startswith("data.")])
    payload = {"data": data, "config": contract["sampleConfig"],
               "template": dict(template, template_id=SAMPLE_TEMPLATE_ID)}
    return json.dumps(payload, ensure_ascii=False, indent=2) + "\n"


def _thumbnail_contract_md(contract):
    return (
        THUMBNAIL_HEADER.format(sources="")
        + f"\n# サムネイルのテンプレート契約 {contract['contract']} の "
          "payload\n\n"
        + contract["description"]["ja"] + "\n\n"
        + "キーの中の記号:\n\n" + _placeholders(contract) + "\n\n"
        + _payload_sections(contract, 2))


def _thumbnail_ai_prompt(contract, agents, samples, payload):
    parts = [
        THUMBNAIL_HEADER.format(sources=", layout/include/kit/thumbnail/"
                                "AGENTS.md.tmpl and layout/include/kit/"
                                "thumbnail/"),
        "\n# Autona のサムネイルのテンプレートを作る（kind `thumbnail`・"
        f"テンプレート契約 {contract['contract']}）\n",
        "この文書だけで作れるように、指示書・payload のキーの表・動くサンプル・"
        "payload の見本をまとめています。"
        "あなた（AI）は利用者の頼みに合わせてサンプルを書き換え、"
        "**`thumbnail.html` / `thumbnail.css` / `thumbnail.js` の全文**"
        "（`template.json` を変えたらそれも）をファイルごとに 1 つのコードブロックで"
        "返してください。利用者はそれを Autona のサムネイルのページの"
        "「新しいデザインを作る」で作ったフォルダ（`layout/thumbnail_<名前>/`）に"
        "上書き保存します。`settings.json` は返さないでください（表示名と作者が"
        "見本の値で上書きされます。大きさを変えるときだけ、変える行を伝えます）。"
        "`../include/` と `../../assets/` の中身は利用者の手元にあるので、"
        "返さなくてよいです。\n",
        "**2 回目以降の直し**では、利用者に今のフォルダの `thumbnail.html` / "
        "`thumbnail.css` / `thumbnail.js`（変えていれば `template.json` も）を"
        "一緒に貼ってもらってください。この文書のサンプルは作った直後のもので、"
        "今のファイルとは違います。エラーを直すときは、Autona の"
        "「AI に貼る用にコピー」の文も貼ってもらいます。\n",
        "## 指示書\n",
        _demote(agents),
        "## payload のキー\n",
        "キーの中の記号:\n\n" + _placeholders(contract) + "\n",
        _payload_sections(contract, 3),
        "## サンプル（今フォルダにあるファイル）\n",
    ]
    for name in THUMBNAIL_FILES:
        parts.append(f"### {name}\n\n```{FENCES[name]}\n"
                     f"{samples[name].rstrip()}\n```\n")
    parts.append(
        f"## payload の見本（{SAMPLE_PAYLOAD}）\n\n"
        "1on1 の試合のときに Autona が `Autona.onRender` に渡すものと同じ形です"
        "（`data` はサムネイルに使うところだけを抜いています。本物の `data` には"
        "ほかのキーもあります）。\n\n"
        f"```json\n{payload.rstrip()}\n```\n")
    return "\n".join(parts)


def _thumbnail_files(layout):
    include = Path(layout) / "include"
    kit = include / "kit" / THUMBNAIL
    contract = json.loads(_read(include / THUMBNAIL_CONTRACT))
    state = json.loads(_read(include / "sample" / f"{SAMPLE_STATE}.json"))
    samples = {name: _read(kit / name) for name in THUMBNAIL_FILES}
    payload = _sample_payload(contract, state,
                              json.loads(samples[THUMBNAIL_TEMPLATE]))
    return {
        f"{THUMBNAIL}/{SAMPLE_PAYLOAD}": payload,
        f"{THUMBNAIL}/CONTRACT.md": _thumbnail_contract_md(contract),
        f"{THUMBNAIL}/AI_PROMPT.md": _thumbnail_ai_prompt(
            contract, _read(kit / AGENTS_TEMPLATE), samples, payload),
    }


# The result's kit (ADR-008 D7 R4): its sample files, and the two sample
# payloads, built here as core/ResultService.BuildPayload builds a payload
# (the rows in slot order, every slot a row, an empty one included) with the
# sample state's tournament and its characters' values.
RESULT = "result"
RESULT_CONTRACT = "result_contract.json"
RESULT_FILES = ("result.html", "result.css", "result.js")
RESULT_TEAMS_PAYLOAD = "sample_payload_teams.json"
# The layout id the sample payloads name: a new design's is its folder.
SAMPLE_LAYOUT_ID = "result_sample"
RESULT_GROUPS = ("data", "config", "layout")
RESULT_TITLES = {
    "data": "payload.data（順位の行と大会の情報）",
    "config": "payload.config（リザルトの画像の設定）",
    "layout": "payload.layout（レイアウトの id）",
}
# How many rows a layout of each kind is handed (ResultService.SlotsFor: a
# players' layout sixteen, a teams' eight).
RESULT_SLOTS = {"players": 16, "teams": 8}
# (rank, name, sponsor, its characters' numbers): a top 8 with ties at 5th
# and 7th, a player without a character; the rest of the sixteen are empty.
SAMPLE_PLAYERS = (
    (1, "Alpha", "TEAM A", (1, 2)), (2, "Bravo", "", (2,)),
    (3, "Charlie", "", (3,)), (4, "Delta", "SP", (0,)),
    (5, "Echo", "", (1,)), (5, "Foxtrot", "", (2,)),
    (7, "Golf", "", (3, 0, 1)), (7, "Hotel", "", ()),
)
# (rank, team name, its members' (name, character number or None)); the
# last of the eight is empty.
SAMPLE_TEAMS = (
    (1, "Crew Alpha", (("Alpha", 1), ("Echo", 2), ("Hotel", 3))),
    (2, "Crew Bravo", (("Bravo", 0), ("Foxtrot", 1), ("Golf", 2))),
    (3, "Crew Charlie", (("Charlie", 3), ("India", 0))),
    (4, "Crew Delta", (("Delta", 1), ("Juliet", 2), ("Kilo", 3),
                       ("Lima", 0), ("Mike", 1))),
    (5, "Crew Echo", (("November", 2),)),
    (5, "Crew Foxtrot", (("Oscar", 3), ("Papa", None), ("Quebec", 0))),
    (7, "Crew Golf", (("Romeo", 1), ("Sierra", 2))),
)
RESULT_HEADER = (
    "<!-- Generated by scripts/gen_layout_kit.py from "
    "layout/include/result_contract.json{sources}. Do not edit: "
    "change the sources and run the script. -->\n")


def _sample_character(state, number):
    """The sample state's character value (board 1, player 1's first) as
    character `number` of the mock assets: the shape a pick writes."""
    model = state["score"][SAMPLE_BOARD]["team"]["1"]["player"]["1"][
        "character"]["1"]
    text = json.dumps(model).replace("Fighter 1", f"Fighter {number}") \
        .replace("fighter_1", f"fighter_{number}") \
        .replace("full_character_1", f"full_character_{number}")
    return json.loads(text)


def _empty_row(rank):
    return {"rank": rank, "name": "", "sponsor": "", "character": {},
            "characters": [], "members": []}


def _result_payload(contract, state, rows):
    """A payload of `rows` ("players" / "teams") as the app hands it."""
    info = state["tournamentInfo"]
    data = {
        "tournamentName": info["tournamentName"],
        "eventName": info["eventName"],
        "startAt": info["startAt"],
        "numEntrants": info["numEntrants"],
        "players": [],
        "rows": rows,
    }
    if rows == "teams":
        for rank, name, members in SAMPLE_TEAMS:
            data["players"].append({
                "rank": rank, "name": name, "sponsor": "", "character": {},
                "characters": [],
                "members": [{"name": member, "character": {} if number is None
                             else _sample_character(state, number)}
                            for member, number in members]})
    else:
        for rank, name, sponsor, numbers in SAMPLE_PLAYERS:
            characters = [_sample_character(state, n) for n in numbers]
            data["players"].append({
                "rank": rank, "name": name, "sponsor": sponsor,
                "character": characters[0] if characters else {},
                "characters": characters, "members": []})
    while len(data["players"]) < RESULT_SLOTS[rows]:
        data["players"].append(_empty_row(len(data["players"]) + 1))
    payload = {"data": data, "config": contract["sampleConfig"],
               "layout": SAMPLE_LAYOUT_ID}
    return json.dumps(payload, ensure_ascii=False, indent=2) + "\n"


def _result_sections(contract, level):
    out = []
    for group in RESULT_GROUPS:
        keys = [row for row in contract["keys"]
                if row["key"].split(".", 1)[0].split("[", 1)[0] == group]
        out.append(f"{'#' * level} {RESULT_TITLES[group]}\n\n"
                   f"{_payload_table(keys)}\n")
    return "\n".join(out)


def _result_contract_md(contract):
    return (
        RESULT_HEADER.format(sources="")
        + f"\n# リザルト画像のテンプレート契約 {contract['contract']} の "
          "payload\n\n"
        + contract["description"]["ja"] + "\n\n"
        + "キーの中の記号:\n\n" + _placeholders(contract) + "\n\n"
        + _result_sections(contract, 2))


def _teams_excerpt(teams):
    """The teams' sample payload's first row, with its first member alone: the
    shape of a teams' row and of a member's character, short."""
    row = dict(json.loads(teams)["data"]["players"][0])
    row["members"] = row["members"][:1]
    return json.dumps(row, ensure_ascii=False, indent=2) + "\n"


def _result_ai_prompt(contract, agents, samples, payload, teams):
    parts = [
        RESULT_HEADER.format(sources=", layout/include/kit/result/"
                             "AGENTS.md.tmpl and layout/include/kit/result/"),
        "\n# Autona のリザルト画像のレイアウトを作る（kind `result`・"
        f"テンプレート契約 {contract['contract']}）\n",
        "この文書だけで作れるように、指示書・payload のキーの表・動くサンプル・"
        "payload の見本をまとめています。"
        "あなた（AI）は利用者の頼みに合わせてサンプルを書き換え、"
        "**`result.html` / `result.css` / `result.js` の全文**"
        "をファイルごとに 1 つのコードブロックで返してください。"
        "利用者はそれを Autona のリザルトのページの"
        "「新しいデザインを作る」で作ったフォルダ（`layout/result_<名前>/`）に"
        "上書き保存します。`settings.json` は返さないでください（下の"
        "「マニフェスト」）。`../include/` と `../../assets/` の中身は利用者の"
        "手元にあるので、返さなくてよいです。\n",
        "**2 回目以降の直し**では、利用者に今のフォルダの `result.html` / "
        "`result.css` / `result.js` を一緒に貼ってもらってください。"
        "この文書のサンプルは作った直後のもので、今のファイルとは違います。"
        "エラーを直すときは、Autona の「AI に貼る用にコピー」の文も"
        "貼ってもらいます。\n",
        "## 指示書\n",
        _demote(agents),
        "## payload のキー\n",
        "キーの中の記号:\n\n" + _placeholders(contract) + "\n",
        _result_sections(contract, 3),
        "## サンプル（今フォルダにあるファイル）\n",
    ]
    for name in RESULT_FILES:
        parts.append(f"### {name}\n\n```{FENCES[name]}\n"
                     f"{samples[name].rstrip()}\n```\n")
    parts.append(
        f"## payload の見本（{SAMPLE_PAYLOAD}）\n\n"
        "個人の Top 8 を入れたときに Autona が `Autona.onRender` に渡すものと"
        "同じ形です（16 行のうち 9 行目からは入力の無い空の行。5 位と 7 位が"
        f"同順位）。チームの見本はフォルダの `{RESULT_TEAMS_PAYLOAD}`"
        "（8 行。`members` に 0〜5 人。最後は入力の無い空の行）。\n\n"
        f"```json\n{payload.rstrip()}\n```\n")
    parts.append(
        f"## チームの行の見本（{RESULT_TEAMS_PAYLOAD} の抜粋）\n\n"
        "`rows` が `\"teams\"` のときの `data.players` の 1 行目です（メンバーは"
        "1 人目だけを載せています。この行は 3 人）。メンバーの `character` は"
        "`players` の行の `character` と同じ形で、`assets` を持ちます"
        "（キャラの無いメンバーは `{}`）。\n\n"
        f"```json\n{_teams_excerpt(teams).rstrip()}\n```\n")
    return "\n".join(parts)


def _result_files(layout):
    include = Path(layout) / "include"
    kit = include / "kit" / RESULT
    contract = json.loads(_read(include / RESULT_CONTRACT))
    state = json.loads(_read(include / "sample" / f"{SAMPLE_STATE}.json"))
    samples = {name: _read(kit / name) for name in RESULT_FILES}
    payload = _result_payload(contract, state, "players")
    teams = _result_payload(contract, state, "teams")
    return {
        f"{RESULT}/{SAMPLE_PAYLOAD}": payload,
        f"{RESULT}/{RESULT_TEAMS_PAYLOAD}": teams,
        f"{RESULT}/CONTRACT.md": _result_contract_md(contract),
        f"{RESULT}/AI_PROMPT.md": _result_ai_prompt(
            contract, _read(kit / AGENTS_TEMPLATE), samples, payload, teams),
    }


def _read(path):
    # Line endings as git checks them out on Windows do not matter.
    return path.read_text(encoding="utf-8").replace("\r\n", "\n")


def Build(layout=LAYOUT):
    """{path relative to layout/include/kit: text} of every generated file."""
    kit = Path(layout) / "include" / "kit"
    contract = json.loads(_read(Path(layout) / "include"
                                / "overlay_contract.json"))
    agents = _read(kit / AGENTS_TEMPLATE)
    files = {"CONTRACT.md": _contract_md(contract)}
    for kind in KINDS:
        samples = {name: _read(kit / kind / name) for name in SAMPLE_FILES}
        files[f"{kind}/AI_PROMPT.md"] = _ai_prompt(
            kind, contract, agents, samples)
    files.update(_thumbnail_files(layout))
    files.update(_result_files(layout))
    return files


def main():
    for relative, text in Build().items():
        path = KIT / relative
        path.write_text(text, encoding="utf-8", newline="\n")
        print(f"wrote {path.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
